urlset:
{%- for entry in entries %}

  {{ entry.permalink | escape_xml | safe }}
  {%- if entry.updated %}
  {{ entry.updated }}
  {%- endif %}
  {%- if entry.extra.sitemap %}
  {%- if entry.extra.sitemap.priority %}
  {{ entry.extra.sitemap.priority}}
  {%- endif %}
  {%- if entry.extra.sitemap.change_frequency %}
  {{ entry.extra.sitemap.change_frequency}}
  {%- endif %}
  {%- elif loop.first %}
  {#- the first item is the root of the site, the homepage #}
  1
  monthly
  {%- endif %}

{%- endfor %}
